import {FISH,UPGRADES,BALANCE} from './config.js';
export const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export function fresh(){return {version:1,money:45,inventory:[],upgrades:Object.fromEntries(Object.keys(UPGRADES).map(k=>[k,0])),fuel:100,hull:100,sold:0,fed:0,intro:false,settings:{quality:'Média',volume:.3},time:9};}
export function restore(raw){const s=fresh();try{const d=JSON.parse(raw);if(!d||typeof d!=='object')return s;for(const k of ['money','fuel','hull','sold','fed','time'])if(Number.isFinite(d[k])&&d[k]>=0)s[k]=d[k];s.fuel=clamp(s.fuel,0,100);s.hull=clamp(s.hull,1,100);for(const k in UPGRADES)s.upgrades[k]=clamp(Math.floor(Number(d.upgrades?.[k])||0),0,UPGRADES[k].max);s.inventory=Array.isArray(d.inventory)?d.inventory.filter(f=>FISH.some(p=>p.id===f.species)&&typeof f.id==='string'&&/^[a-zA-Z0-9_.-]{1,80}$/.test(f.id)&&Number.isFinite(f.weight)&&f.weight>0&&f.weight<=22).filter((f,i,a)=>a.findIndex(g=>g.id===f.id)===i).map(f=>({id:f.id,species:f.species,weight:f.weight})):[];s.intro=!!d.intro;s.settings.quality=['Baixa','Média','Alta'].includes(d.settings?.quality)?d.settings.quality:'Média';s.settings.volume=clamp(Number(d.settings?.volume) || 0,0,1);}catch{}return s;}
export class Economy{constructor(state){this.s=state;}get weight(){return this.s.inventory.reduce((a,b)=>a+b.weight,0);}get capacity(){return 12+this.s.upgrades.hold*12;}price(f){return Math.round(FISH.find(p=>p.id===f.species).price*f.weight);}sell(id){const batch=this.s.inventory.filter(f=>id==='all'||f.id===id);const total=batch.reduce((a,f)=>a+this.price(f),0);this.s.inventory=this.s.inventory.filter(f=>!batch.includes(f));this.s.money+=total;this.s.sold+=batch.length;return total;}buy(k){const u=UPGRADES[k],level=this.s.upgrades[k];if(!u||level>=u.max||this.s.money<u.prices[level])return false;this.s.money-=u.prices[level];this.s.upgrades[k]++;return true;}service(k){const cost={fuel:BALANCE.fuelPrice,hull:BALANCE.repairPrice,food:BALANCE.foodPrice}[k];if(!cost||this.s.money<cost||(k!=='food'&&this.s[k]>=100))return false;this.s.money-=cost;if(k==='food')this.s.fed++;else this.s[k]=100;return true;}add(f){if(this.weight+f.weight>this.capacity)return false;this.s.inventory.push(f);return true;}}
export {FishingSystem,castProfile,bobberPos,pingPong,CAST,rarityInfo} from './fishing.js';
export class SharkAI{constructor(rng=Math.random){this.rng=rng;this.reset();}reset(){this.state='away';this.timer=120+this.rng()*120;this.distance=55;this.hp=3;this.cooldown=0;}update(dt,open){this.cooldown=Math.max(0,this.cooldown-dt);if(!open){this.reset();return 0;}this.timer-=dt;if(this.state==='away'&&this.timer<=0){this.state='patrol';this.timer=6;this.distance=45;this.hp=3;}else if(this.state==='patrol'&&this.timer<=0){this.state='approach';}else if(this.state==='approach'){this.distance=Math.max(7,this.distance-dt*5);if(this.distance<=7){this.state='alert';this.timer=3;}}else if(this.state==='alert'&&this.timer<=0){this.state='attack';}else if(this.state==='attack'){this.distance-=dt*6;if(this.distance<=2){this.state='retreat';this.timer=6;return 18;}}else if(this.state==='retreat'){this.distance+=dt*5;if(this.timer<=0){if(this.hp<=0)this.reset();else this.state='approach';}}return 0;}hit(range){if(this.cooldown||this.distance>range||!['approach','alert','attack'].includes(this.state))return false;this.cooldown=.8;this.hp--;this.state='retreat';this.timer=this.hp<=0?10:4;return true;}}
